/* Base resets and palette (Dark Slate, Warm Cream, Matcha Green, Terracotta) */
:root {
  --bg-color: #262b44;
  --card-bg: #3a4466;
  --accent-light: #fbf5ef;
  --accent-green: #68c279;
  --accent-dark: #1b1e34;
  --accent-warm: #d97559;
  --pixel-border: 4px solid var(--accent-dark);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  image-rendering: pixelated;
}

/* Ensure hidden attribute is never overridden by display styles */
[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

body {
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  line-height: 1.4;
  background-color: var(--bg-color);
  color: var(--accent-light);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.app-container {
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  margin: 0 auto;
}

.timer-card {
  background-color: var(--card-bg);
  border: var(--pixel-border);
  box-shadow: 6px 6px 0px var(--accent-dark);
  padding: 1.5rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.title {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--accent-light);
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--accent-dark);
}

.pixel-art-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100px;
}

#teaCanvas {
  image-rendering: pixelated;
  width: 96px;
  height: 96px;
}

.preset-fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

.preset-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.sub-time {
  font-size: 0.85rem;
  opacity: 0.9;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  background-color: var(--accent-light);
  color: var(--accent-dark);
  border: 3px solid var(--accent-dark);
  box-shadow: 3px 3px 0px var(--accent-dark);
  padding: 0.6rem 0.5rem;
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
  user-select: none;
}

.pixel-btn:hover:not(:disabled) {
  background-color: #ffffff;
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0px var(--accent-dark);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--accent-light);
  outline-offset: 3px;
}

.pixel-btn:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: 0px 0px 0px var(--accent-dark);
}

.preset-btn.active {
  background-color: var(--accent-green);
  color: var(--accent-dark);
  box-shadow: inset 2px 2px 0px rgba(0,0,0,0.2);
}

.pixel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: 2px 2px 0px var(--accent-dark);
  transform: none;
}

.display-panel {
  background-color: var(--accent-dark);
  border: 3px solid #141726;
  padding: 1rem;
  min-height: 95px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 0.35rem;
}

.time-display {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: 3px;
  color: var(--accent-light);
  text-shadow: 2px 2px 0px rgba(0, 0, 0, 0.4);
}

.status-message {
  font-size: 1rem;
  font-weight: bold;
  color: var(--accent-warm);
  letter-spacing: 1px;
  animation: blink 0.9s infinite alternate ease-in-out;
}

@keyframes blink {
  from { opacity: 0.3; }
  to { opacity: 1; }
}

.control-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

.action-btn.primary {
  background-color: var(--accent-green);
}

.action-btn.secondary {
  background-color: var(--accent-warm);
}

(function () {
  const presets = {
    Green: 120,
    Black: 240,
    Herbal: 360
  };

  let currentTea = 'Green';
  let totalSeconds = presets[currentTea];
  let remainingSeconds = totalSeconds;
  let timerId = null;
  let isRunning = false;

  // Elements
  const timeDisplay = document.getElementById('timeDisplay');
  const statusMessage = document.getElementById('statusMessage');
  const startBtn = document.getElementById('startBtn');
  const cancelBtn = document.getElementById('cancelBtn');
  const presetButtons = document.querySelectorAll('.preset-btn');
  const canvas = document.getElementById('teaCanvas');

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    const mm = m.toString();
    const ss = s < 10 ? '0' + s : s.toString();
    return mm + ':' + ss;
  }

  function updateDisplay() {
    timeDisplay.textContent = formatTime(remainingSeconds);
  }

  function drawPixelTeacup(progress) {
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    const s = 4; // Pixel size multiplier (24x24 logical grid)

    ctx.clearRect(0, 0, 96, 96);

    const teaColors = {
      Green: '#7bb35c',
      Black: '#8c4b2d',
      Herbal: '#d66d75'
    };
    const liquidColor = teaColors[currentTea] || '#7bb35c';

    // Cup base and rim coordinates
    ctx.fillStyle = '#1b1e34';
    // Rim outline
    ctx.fillRect(4 * s, 10 * s, 14 * s, 1 * s);
    // Left wall
    ctx.fillRect(4 * s, 11 * s, 1 * s, 8 * s);
    // Right wall
    ctx.fillRect(17 * s, 11 * s, 1 * s, 8 * s);
    // Bottom outline
    ctx.fillRect(5 * s, 19 * s, 12 * s, 1 * s);
    // Saucer
    ctx.fillRect(3 * s, 21 * s, 16 * s, 1 * s);

    // Cup handle
    ctx.fillRect(18 * s, 12 * s, 3 * s, 1 * s);
    ctx.fillRect(20 * s, 13 * s, 1 * s, 4 * s);
    ctx.fillRect(18 * s, 16 * s, 3 * s, 1 * s);

    // Cup body porcelain
    ctx.fillStyle = '#fbf5ef';
    ctx.fillRect(5 * s, 11 * s, 12 * s, 8 * s);

    // Tea liquid filling (height scales down with progress if desired or remains full)
    ctx.fillStyle = liquidColor;
    ctx.fillRect(6 * s, 13 * s, 10 * s, 5 * s);

    // Steam puffs if running
    if (isRunning && remainingSeconds > 0) {
      ctx.fillStyle = 'rgba(251, 245, 239, 0.7)';
      const alt = remainingSeconds % 2 === 0;
      if (alt) {
        ctx.fillRect(8 * s, 7 * s, 2 * s, 2 * s);
        ctx.fillRect(12 * s, 5 * s, 2 * s, 2 * s);
      } else {
        ctx.fillRect(7 * s, 5 * s, 2 * s, 2 * s);
        ctx.fillRect(13 * s, 7 * s, 2 * s, 2 * s);
      }
    }
  }

  function stopTimer() {
    if (timerId !== null) {
      clearInterval(timerId);
      timerId = null;
    }
    isRunning = false;
  }

  function setPreset(name) {
    if (isRunning) return;
    currentTea = name;
    totalSeconds = presets[name];
    remainingSeconds = totalSeconds;
    statusMessage.hidden = true;

    presetButtons.forEach(btn => {
      const isMatch = btn.getAttribute('data-name') === name;
      btn.classList.toggle('active', isMatch);
      btn.setAttribute('aria-pressed', isMatch ? 'true' : 'false');
    });

    updateDisplay();
    drawPixelTeacup(1);
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      updateDisplay();
      drawPixelTeacup(remainingSeconds / totalSeconds);
    }

    if (remainingSeconds <= 0) {
      stopTimer();
      startBtn.disabled = false;
      cancelBtn.disabled = true;
      presetButtons.forEach(btn => (btn.disabled = false));
      statusMessage.textContent = 'Your tea is ready';
      statusMessage.hidden = false;
      drawPixelTeacup(0);
    }
  }

  function onStart() {
    if (isRunning) return;

    if (remainingSeconds <= 0) {
      remainingSeconds = totalSeconds;
      updateDisplay();
    }

    statusMessage.hidden = true;
    isRunning = true;
    startBtn.disabled = true;
    cancelBtn.disabled = false;
    presetButtons.forEach(btn => (btn.disabled = true));

    timerId = setInterval(tick, 1000);
    drawPixelTeacup(remainingSeconds / totalSeconds);
  }

  function onCancel() {
    stopTimer();
    remainingSeconds = totalSeconds;
    updateDisplay();
    statusMessage.hidden = true;
    startBtn.disabled = false;
    cancelBtn.disabled = true;
    presetButtons.forEach(btn => (btn.disabled = false));
    drawPixelTeacup(1);
  }

  // Event listeners
  startBtn.addEventListener('click', onStart);
  cancelBtn.addEventListener('click', onCancel);

  presetButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const name = btn.getAttribute('data-name');
      if (name) {
        setPreset(name);
      }
    });
  });

  // Initial render
  updateDisplay();
  drawPixelTeacup(1);
})();
